#include <dev/console.h>
#include <dev/syscall.h>
#include <memfs/memfs.h>
#include <tcm_bsp.h>
#include <tcm_config.h>
#include <tcm_format.h>

#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/unistd.h>
#include <time.h>

// NOLINTBEGIN
// Heap boundary for picolibc malloc() / free()
uintptr_t __heap_start = 0;
uintptr_t __heap_end = TCM_HEAP_LIMIT_ADDR;
// NOLINTEND

extern int main(int argc, char *argv[]);

// Generated by llvm-link-tcmips for picolibc global constructors/destructors
extern void TCM_SYMBOL_CTORS(void);
extern void TCM_SYMBOL_DTORS(void);

struct timeval __tcm_startup_time; // NOLINT

void cstart(void) {
  gettimeofday(&__tcm_startup_time, NULL);

  volatile TCMImageHeader *image = (volatile TCMImageHeader *)0;

  // Align heap to 256-byte boundary after image to avoid overwrite
  __heap_start = (image->w_imagesize + 0xFF) & ~0xFF;

  setenv("TZ", "UTC-8", 1);
  setenv("HOME", "/", 1);
  setenv("PATH", "/", 1);
  tzset();

  tcm_syscall_seven_segment_display_upper(0, 0);
  tcm_syscall_seven_segment_display_lower(0, 0);

  // Initialise the in-memory filesystem. memfs_init() picks up the payload
  // provided by the linker when one is packed (--tcm-memfs=<dir>); otherwise
  // libmemfs supplies weak placeholders (size 0), producing an empty directory.
  // MEMFS_BASE_FD leaves the POSIX standard fds 0/1/2 (stdin/stdout/stderr) to
  // the console; memfs allocates its regular fds from there upward.
  memfs_init(MEMFS_BASE_FD);

  // Provide a writable temp directory and expose it to libraries such as
  // libc++ <filesystem> temp_directory_path(). best-effort: EEXIST means a
  // packed /tmp already exists and is fine.
  if (mkdir("/tmp", 0777) != 0 && errno != EEXIST) {
    // Fall back to the root if /tmp cannot be created for any other reason.
    setenv("TMPDIR", "/", 1);
  } else {
    setenv("TMPDIR", "/tmp", 1);
  }

  void *vram = tcm_pixel_console_init(CONSOLE_MODE_PIXEL_32, 160);

  // Boot logo: raw 160x120 RGBA pixels (R,G,B,A per pixel, top-down, no padding)
  // packed by the linker at /tcmips/logos/logo.bin (see bsp/assets and
  // tcmips_bsp's -tcm-memfs). memfs_map() returns a zero-copy pointer for packed
  // assets; when the asset is absent (e.g. an unpacked empty image) we simply
  // leave the framebuffer dark rather than dereferencing NULL.
  {
    size_t logo_len = 0;
    const void *logo = memfs_map("/tcmips/logos/logo.bin", &logo_len);
    if (logo && logo_len == (size_t)(160 * 120 * 4))
      memcpy(vram, logo, logo_len);
  }

  tcm_text_console_init();

  TCM_SYMBOL_CTORS();
  char *argv[] = {(char *)image->filename, NULL};
  int ret = main(1, argv);
  TCM_SYMBOL_DTORS();

  exit(ret);
}

// Boot entry: set up $sp to the stack top, then jump to cstart().
__attribute__((naked, noreturn)) void TCM_SYMBOL_START(void) {
#if TCM_STACK_TOP_ADDR & 0xFFFF
#error "TCM_STACK_TOP_ADDR must be 64KB aligned"
#endif

#define TCM_STACK_TOP_HI16 ((TCM_STACK_TOP_ADDR >> 16) & 0xFFFF)
  __asm__ __volatile__( //
      ".set push\n\t"
      ".set noreorder\n\t"
      "jal  %[CSTART]\n\t"
      "lui $sp, %[STACK]\n\t"
      ".set pop\n\t"
      :
      : [CSTART] "i"(cstart), [STACK] "i"(TCM_STACK_TOP_HI16));
#undef TCM_STACK_TOP_HI16
}
